import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.DnrXFDHb.js";const h=JSON.parse('{"title":"infrastructure 层总览","description":"Infrastructure 层的职责、组成与扩展方式","frontmatter":{"title":"infrastructure 层总览","description":"Infrastructure 层的职责、组成与扩展方式"},"headers":[],"relativePath":"architecture/infrastructure/overview.md","filePath":"architecture/infrastructure/overview.md","lastUpdated":1773326634000}'),i={name:"architecture/infrastructure/overview.md"};function o(c,e,s,d,u,l){return a(),r("div",null,[...e[0]||(e[0]=[n(`<h1 id="infrastructure-层总览" tabindex="-1">infrastructure 层总览 <a class="header-anchor" href="#infrastructure-层总览" aria-label="Permalink to &quot;infrastructure 层总览&quot;">​</a></h1><p><strong>源文件</strong>：<code>src/streammuse/infrastructure/</code></p><p>Infrastructure 层是 Clean Architecture 的最外层，包含所有与外部世界交互的具体实现：MIDI 设备、文件系统、HTTP 服务器、ML 模型等。</p><hr><h2 id="职责" tabindex="-1">职责 <a class="header-anchor" href="#职责" aria-label="Permalink to &quot;职责&quot;">​</a></h2><ul><li>实现 Domain 接口（<code>InputSource</code>、<code>OutputSink</code>、<code>InferenceEngine</code>）的具体类</li><li>管理所有外部 I/O（MIDI 端口、文件读写、HTTP 请求、键盘监听）</li><li><strong>不包含任何业务逻辑</strong>：业务规则留在 Domain 层</li></ul><hr><h2 id="依赖方向" tabindex="-1">依赖方向 <a class="header-anchor" href="#依赖方向" aria-label="Permalink to &quot;依赖方向&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Application/Domain  ←（依赖）  Infrastructure</span></span></code></pre></div><p>Infrastructure 层可以导入 Domain 层（使用 Domain 的接口和类型），但 Domain 层<strong>绝不</strong>导入 Infrastructure 层。</p><hr><h2 id="组成" tabindex="-1">组成 <a class="header-anchor" href="#组成" aria-label="Permalink to &quot;组成&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>infrastructure/</span></span>
<span class="line"><span>├── input/            # InputSource 实现（键盘、MIDI 设备、MIDI 文件、列表）</span></span>
<span class="line"><span>├── output/           # OutputSink 实现（控制台、音频、文件、WebSocket、日志）</span></span>
<span class="line"><span>└── inference/        # InferenceEngine 实现（HTTP 客户端、Stanley 本地引擎）</span></span></code></pre></div><hr><h2 id="各子模块概述" tabindex="-1">各子模块概述 <a class="header-anchor" href="#各子模块概述" aria-label="Permalink to &quot;各子模块概述&quot;">​</a></h2><table tabindex="0"><thead><tr><th>子模块</th><th>实现</th><th>Domain 接口</th></tr></thead><tbody><tr><td><code>input/</code></td><td><code>KeyboardInput</code>, <code>MidiDeviceInput</code>, <code>MidiFileInput</code>, <code>ListInput</code></td><td><code>InputSource</code></td></tr><tr><td><code>output/</code></td><td>7 种 OutputSink 实现</td><td><code>OutputSink</code></td></tr><tr><td><code>inference/</code></td><td><code>HttpInferenceClient</code>, <code>StanleyInferenceEngine</code></td><td><code>InferenceEngine</code></td></tr></tbody></table><hr><h2 id="详细文档" tabindex="-1">详细文档 <a class="header-anchor" href="#详细文档" aria-label="Permalink to &quot;详细文档&quot;">​</a></h2><ul><li><a href="./input/overview.html">input/overview.md</a> — 四种输入适配器</li><li><a href="./output/overview.html">output/overview.md</a> — 七种输出适配器</li><li><a href="./inference/overview.html">inference/overview.md</a> — 两种推理引擎</li></ul>`,19)])])}const f=t(i,[["render",o]]);export{h as __pageData,f as default};
